window.DGNL_DE_MON["l15"] = {"id": "l15", "ten": "Đề thi thử số 15", "tv": [{"noiDungChung": null, "cauHoi": [{"question": "<i>“Thần Mưa là vị thần hình rồng, thường bay xuống hạ giới hút nước biển, nước sông vào bụng rồi bay lên trời cao phun nước ra làm mưa cho thế gian có nước uống và cày cấy, cây cỏ trên mặt đất được tốt tươi. Thần Mưa thường theo lệnh Trời đi phân phát nước ở các nơi. Thần Mưa có tính hay quên, có vùng cả năm không đến, sinh ra hạn hán ở hạ giới, có vùng lại đến luôn, làm thành lụt lội.”</i><br>(Thần thoại Việt Nam, <i>Truyện Thần Mưa</i>)<br>Đâu là ý nghĩa của đoạn trích trên?", "choices": ["Giải thích nguồn gốc loài người", "Giải thích đặc điểm muôn loài.", "Giải thích hiện tượng tự nhiên", "Giải thích nguồn gốc vũ trụ"], "correctIndex": 2, "explain": "<b>Câu 1 chọn C Giải thích: Đoạn trích về Thần Mưa dùng để giải thích các hiện tượng tự nhiên như mưa, hạn hán và lụt lội dưới góc nhìn thần thoại.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Khi ấy, trời đất mới sinh, đã có cây cỏ, muôn thú mà chưa có loài người. Thế giới giống như một bức tranh buồn tẻ. Đi giữa thế giới hoang sơ, buồn tẻ ấy là vị đại thiên thần, chính là Nữ Oa. Lúc ấy, bà cảm thấy buồn chán, cô độc bèn nghĩ rằng cần phải tạo ra một cái gì đó cho thế giới này thêm vui tươi, giàu sức sống. Bà nghĩ ngợi hồi lâu, rồi đến bên đầm nước, lấy bùn đất màu vàng bên bờ đầm, trộn nhuyễn với nước, mô phỏng theo hình dáng của mình in bóng trên mặt nước mà nặn thành đồ vật xinh xắn, đáng yêu. Lạ thay, vừa đặt xuống mặt đất, đồ vật xinh xắn ấy bỗng dưng có sức sống, cất tiếng nói trong trẻo, nhảy múa, vui đùa. Đồ vật xinh xắn ấy gọi là Người”</i><br>(Thần thoại Trung Quốc, <i>Nữ Oa</i>)<br>Đâu là biện pháp tu từ có trong đoạn trích trên?", "choices": ["So sánh và liệt kê", "Nhân hoá và ẩn dụ", "Nói quá và hoán dụ", "Điệp cấu trúc và so sánh"], "correctIndex": 0, "explain": "<b>Câu 2 chọn A</b> Giải thích: Đoạn trích sử dụng biện pháp <b>so sánh</b> (&quot;Thế giới giống như một bức tranh buồn tẻ&quot;, &quot;mô phỏng theo hình dáng của mình&quot;) và <b>liệt kê</b> các hành động của Nữ Oa (lấy bùn, trộn nhuyễn, nặn thành đồ vật...)"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>“Giậu thưa thưa hai khóm trúc,</i><br><i>Giường thấp thấp một nồi hương.</i><br><i>Vượn chim kết bạn non nước quạnh,</i><br><i>Cầm sách cùng nhau ngày tháng trường.</i><br><i>Hài cỏ đẹp chân đi đủng đỉnh,</i><br><i>Áo bô quen cật vận xuềnh xoàng.</i><br><i>Bốn dân nghiệp có cao cùng thấp,</i><br><i>Đều hết làm tôi thánh thượng hoàng.”</i><br>(Nguyễn Trãi, <i>Tức Sự 4</i>)<br>Có bao nhiêu từ láy trong đoạn trích trên?", "choices": ["2 từ", "3 từ", "4 từ", "5 từ"], "correctIndex": 2, "explain": "<b>Câu 3 chọn C Giải thích: Trong đoạn trích có 4 từ láy là: <i>thưa thưa</i>, <i>thấp thấp</i>, <i>đúng đĩnh</i>, <i>xuềnh xoàng</i>.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i><b>“</i></b><i>Tôi mất một tuần mới bình phục hoàn toàn. Nỗi buồn trong tôi không bắt nguồn từ đau đớn hay những cú đánh. Ở nhà, mọi người bắt đầu đối xử với tôi tốt đến mức có phần hơi kỳ. Nhưng một cái gì đó đã mất. Một cái gì đó quan trọng có thể khiến tôi trở lại là chính mình, khiến tôi có thể tin vào người khác, tin rằng họ là người tốt. Tôi trở nên câm lặng, thờ ơ, gần như lúc nào cũng ngồi bên Pinkie, thất thần nhìn thế giới xung quanh”</i><br>(Joses Mauro De Vasconcelos, <i>Cây cam ngọt của tôi</i>)<br>Văn bản trên sử dụng ngôi kể:", "choices": ["Ngôi thứ nhất", "Ngôi thứ ba hạn tri", "Ngôi thứ hai", "Ngôi thứ ba toàn tri"], "correctIndex": 0, "explain": "<b>Câu 4 chọn A</b> Giải thích: Văn bản sử dụng đại từ &quot;Tôi&quot;, cho thấy người kể chuyện trực tiếp tham gia vào câu chuyện, tức là ngôi thứ nhất."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>“Cô đơn thay là cảnh thân tù!</i><br><i>Tai mở rộng và lòng sôi rạo rực</i><br><i>Tôi lắng nghe tiếng đời lăn náo nức</i><br><i>Ở kia vui sướng biết bao nhiêu!</i><br><i>Nghe chim reo trong gió mạnh lên triều</i><br><i>Nghe vội vã tiếng dơi chiều đập cánh</i><br><i>Nghe lạc ngựa rùng chân bên giếng lạnh</i><br><i>Dưới đường xa nghe tiếng guốc đi về...”</i> <i>(</i>Tố Hữu, <i>Tâm tư trong tù)</i><br>Đâu là nhận định <b>không</b> đúng về đoạn thơ trên?", "choices": ["Đoạn thơ đặt cái tôi trữ tình trong thế đối lập giữa không gian tù ngục cô đơn và đời sống bên ngoài đang chuyển động náo nức, qua đó làm nổi bật khát vọng được giao cảm với cuộc đời.", "Điệp từ “nghe” kết hợp với các từ ngữ thuộc trường thính giác như “tai”, “lắng nghe”, “tiếng” cho thấy cảm giác nghe trở thành phương thức giúp người tù hướng ra thế giới bên ngoài.", "Các âm thanh “chim reo”, “tiếng dơi chiều đập cánh”, “lạc ngựa rùng chân”, “tiếng guốc đi về” gợi một thế giới bên ngoài sống động, có cả thiên nhiên và con người.", "Những âm thanh bên ngoài tuy được cảm nhận trong trạng thái xa cách, mơ hồ, nhưng cái tôi trữ tình vẫn giữ lòng lạc quan giữa chốn tù đày."], "correctIndex": 3, "explain": "<b>Câu 5 chọn D</b> Giải thích: Nhận định D không đúng vì tâm trạng của người tù trong đoạn thơ này là sự ngột ngạt, cô đơn và khát vọng tự do cháy bỏng, không phải là sự &quot;lạc quan&quot; bình thản"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i><b>“</i></b><i>Thương hại thay! Hoa có một cành, tuyết có một quãng, nguyệt có một vầng, mây có một đóa. Thân là thân hiếm hoi chừng ấy, nỡ nào lấy đôi mươi năm, làm một kiếp, mà ngơm ngớm chốn non Bồng nước Nhược, chút gì không đoái đến cõi phù sinh!”</i><br>(Phạm Thái, <i>Văn tế Trương Quỳnh Như</i>)<br>Dòng nào sau đây <b>không </b>thể hiện đặc điểm nghệ thuật của đoạn trích trên:", "choices": ["Sử dụng thủ pháp nhân hoá", "Sử dụng thủ pháp liệt kê", "Sử dụng điển cố, điển tích", "Sử dụng lối văn biền ngẫu."], "correctIndex": 0, "explain": "<b>Câu 6 chọn A</b> Giải thích: Đoạn trích sử dụng liệt kê (hoa, tuyết, nguyệt, mây), điển cố (non Bồng, nước Nhược) và lối văn biền ngẫu sóng đôi, nhưng không sử dụng thủ pháp nhân hóa."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“… là loại văn xuôi tự sự, phát triển mạnh mẽ thời trung đại, dùng yếu tố kì ảo làm phương thức nghệ thuật để phản ánh cuộc sống”</i><br>Điền vào dấu “…”", "choices": ["Truyện truyền kì", "Truyện truyền thuyết", "Truyện trinh thám.", "Truyện thơ Nôm"], "correctIndex": 0, "explain": "<b>Câu 7 chọn A</b> Giải thích: Truyện truyền kỳ là loại văn xuôi tự sự trung đại thường xuyên sử dụng các yếu tố kỳ ảo để phản ánh đời sống"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Đủng đỉnh chiều hôm dắt tay,</i><br><i>Trong thế giới phút chim bay.</i><br><i>Non cao non thấp mây thuộc,</i><br><i>Cây cứng cây mềm gió …”</i><br>(Nguyễn Trãi, <i>Mạn Thuật 4</i>)<br>Chọn từ điền vào dấu “…”:", "choices": ["đẩy", "buộc", "hay", "may"], "correctIndex": 2, "explain": "<i class=\"canh-bao-lg\">(Lưu ý: lời giải gốc ghi đáp án B, còn đáp án tô trong đề là C — web đang dùng C.)</i><br><b>Câu 8 chọn B Giải thích: Dựa vào quy luật gieo vần và ngữ nghĩa của bài thơ &quot;Mạn Thuật 4&quot; của Nguyễn Trãi, từ phù hợp nhất để điền vào là &quot;buộc&quot; (Cây cứng cây mềm gió buộc)</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>LA ME-CLUY-SƠ: Thế chúng tôi có phải cởi áo ngoài không, thưa ông?</i><br><i>ÁC-PA-GÔNG: Có, nhưng khi nào thấy khách đến đã, và giữ gìn kĩ chớ làm hỏng y phục.</i><br><i>BRANH-ĐA-VOAN: Thưa ông, ông đã biết rõ, vạt trước áo vét dài của tôi bị một vết dầu đèn to tướng.</i><br><i>LA ME-CLUY-SƠ: Còn tôi, thưa ông, quần của tôi thì thủng đít và, nói lỗi phép, người ta nhìn thấy...</i><br><i>ÁC-PA-GÔNG (nói với La Me-cluy-sơ): Im! Liệu khéo quay cái đó vào phía tường và lúc nào cũng quay đàng trước ra phía khách là được. (Ác-pa-gông đặt chiếc mũ trước áo của mình để chỉ cho Branh-đa-voan phải làm thế nào để che vết dầu).</i><br>(Mô-li-e, <i>Lão hả tiện</i>)<br>Trong đoạn thoại trên, mục đích chủ yếu của ông Ác-pa –gông khi bày cách cho đầy tớ che quần thủng và vết dầu trên áo là gì?", "choices": ["Để chứng tỏ mình là người luôn cẩn trọng và lịch sự.", "Để không phải tốn tiền mua trang phục mới cho đầy tớ", "Để răn đe, nhắc nhở về sự luôm thuộm của đầy tớ.", "Không muốn đầy tớ khiếm nhã trước mặt khách."], "correctIndex": 1, "explain": "<b>Câu 9 chọn B Giải thích: Ác-pa-gông là nhân vật điển hình cho tính keo kiệt (lão hạ tiện), việc bày cách che vết bẩn/thủng là để tận dụng đồ cũ, tránh phải tốn tiền mua đồ mới cho đầy tớ.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><table class=\"bang-de\"><tr><td><b>Thơ</b></td><td><b>Bản dịch</b></td></tr><tr><td><i>“Ngục trung hốt thính tư hương khúc,</i><br><i>Thanh chuyển thê lương điệu chuyển sầu.</i><br><i>Thiên lý quan hà vô hạn cảm,</i><br><i>Khuê nhân cánh thướng nhất tằng lâu.”</i><br>(Hồ Chí Minh, <i>Nạn hữu xuy địch</i>)</td><td><i>“Bỗng nghe trong ngục sáo vi vu,</i><br><i>Khúc nhạc tình quê chuyển điệu sầu;</i><br><i>Muôn dặm quan hà, khôn xiết nỗi,</i><br><i>Lên lầu ai đó ngóng trông nhau.”</i><br>(Nam Trân dịch, Người bạn tù thổi sáo)</td></tr></table><br>Ý nào sao đây <b>không được thể hiện </b>trong bài thơ:", "choices": ["Bài thơ thể hiện nghị lực phi thường của người tù cách mạng.", "Bài thơ có sự kết hợp nhuần nhuyễn giữa chất cổ điển và chất hiện đại", "Bài thơ được viết theo thể thơ tứ tuyệt hàm súc, tinh tế", "Bài thơ thể hiện tấm lòng thương cảm của nhà thơ"], "correctIndex": 0, "explain": "<b>Câu 10 chọn A</b> Giải thích: Bài thơ &quot;Nạn hữu xuy địch&quot; chủ yếu thể hiện nỗi lòng nhớ quê hương và sự đồng cảm giữa những người cảnh ngộ, không trực tiếp nhấn mạnh vào &quot;nghị lực phi thường&quot; như các bài khác trong Nhật ký trong tù"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Hai anh em chúng tôi vừa cuộn kín trong chăn cho ấm vừa nói chuyện. Chúng tôi nghĩ đến, rồi thương hại những người lữ khách vào giờ này hãy còn trên đường vắng, ướt như chuột lột và run như cầy sấy, đi vội vàng để tìm một chỗ trú thân. Chúng tôi lại ái ngại cho những nhà nghèo bên hàng xóm, giờ này vợ chồng con cái đều phải dậy để chống cái nhà lá mà mỗi cơn gió mạnh làm lung lay và để đem cái chậu thau hứng những chỗ dột nước.”</i><br>(Thạch Lam, <i>Tiếng chim kêu</i>)<br>Nội dung của đoạn trích trên là gì?", "choices": ["Diễn tả lòng thương người của nhân vật của hai anh em.", "Diễn tả cuộc sống êm ấm, hạnh phúc của nhân vật hai anh em", "Diễn tả hành động cao đẹp cứu giúp người khác của nhân vật hai anh em.", "Diễn tả sự ngây thơ, hồn nhiên của nhân vật hai anh em."], "correctIndex": 0, "explain": "<b>Câu 11 chọn A</b> Giải thích: Đoạn trích diễn tả tâm trạng &quot;thương hại&quot;, &quot;ái ngại&quot; của hai anh em đối với những người lữ khách và hàng xóm nghèo khó trong đêm mưa gió"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Dòng nào sau đây nêu đúng tên những tác phẩm thuộc trường phái văn học lãng mạn?", "choices": ["Nửa chừng xuân (Khái Hưng), Vội Vàng (Xuân Diệu), Tắt đèn (Ngô Tất Tố).", "Chí Phèo (Nam Cao), Nửa chừng xuân (Khái Hưng), Số Đỏ (Vũ Trọng Phụng).", "Chữ người tử tù (Nguyễn Tuân), Nửa chừng xuân (Khái Hưng), Vội Vàng (Xuân Diệu).", "Chữ người tử tù (Nguyễn Tuân), Số Đỏ (Vũ Trọng Phụng), Vội vàng (Xuân Diệu)."], "correctIndex": 2, "explain": "<b>Câu 12 chọn C</b> Giải thích: <i>Chữ người tử tù</i> (Nguyễn Tuân), <i>Nửa chừng xuân</i> (Khái Hưng), <i>Vội Vàng</i> (Xuân Diệu) đều là các tác phẩm tiêu biểu của văn học lãng mạn. (Trong khi đó <i>Tắt đèn</i>, <i>Chí Phèo</i>, <i>Số Đỏ</i> thuộc văn học hiện thực) ."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Trong những từ sau, từ nào viết đúng chính tả?", "choices": ["Chửng đoán", "Ngang tàn", "Trăn trối", "Xán lạn"], "correctIndex": 3, "explain": "<b>Câu 13 chọn D</b> Giải thích: &quot;Xán lạn&quot; là từ viết đúng chính tả. Các từ còn lại sai: chẩn đoán (không phải chửng), ngang tàng (không phải tàn), trăn trối (thường dùng trăng trối tùy ngữ cảnh nhưng xán lạn là đáp án chuẩn nhất)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Tuần trước, chủ tịch tỉnh và bà xã đi thăm hỏi, động viên bà con có hoàn cảnh khó khăn”</i><br>Câu văn trên mắc lỗi:", "choices": ["Dùng từ không đúng nghĩa", "Dùng từ sai chính tả", "Dùng từ sai vị trí", "Dùng từ không hợp phong cách"], "correctIndex": 3, "explain": "<b>Câu 14 chọn D</b> Giải thích: Từ &quot;bà xã&quot; là từ ngữ thuộc phong cách sinh hoạt, khẩu ngữ, không phù hợp để dùng trong câu văn trang trọng nói về chức danh chính trị như &quot;chủ tịch tỉnh&quot;."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Em hãy chọn phương án <b>không</b> chứa từ mượn phương Tây.", "choices": ["Tôi vẫn còn giữ chiếc khăn voan mà anh tặng tôi vào đêm hẹn hò lãng mạn.", "Chiếc ô tô đang đậu đằng kia giờ đây đã thuộc quyền sở hữu của tôi.", "Hôn nhân của cô ấy được tổ chức tại nhà hàng sang trọng.", "Đôi giày bốt mang lại cho cô ấy sự tự tin chưa bao giờ thấy."], "correctIndex": 2, "explain": "<b>Câu 15 chọn C</b> Giải thích: Các câu A, B, D chứa từ mượn gốc Pháp/Anh: voan (voile), ô tô (auto), bốt (boot). Câu C không chứa từ mượn phương Tây."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Những người khốn khổ, một tác phẩm được sáng tác bằng bút pháp lãng mạn của nhà văn Victor Hugo”</i><br>Câu văn trên mắc lỗi gì?", "choices": ["Sắp xếp sai thành phần", "Thiếu chủ ngữ", "Thiếu vị ngữ", "Thiếu cả chủ ngữ và vị ngữ"], "correctIndex": 2, "explain": "<b>Câu 16 chọn C</b> Giải thích: Câu văn mới chỉ có cụm danh từ (Chủ ngữ + thành phần chú thích), chưa có động từ/tính từ để làm vị ngữ hoàn thiện ý nghĩa."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Không có sự cao thấp giữa một người lao động trí óc hay một người công nhân vì họ đều đóng góp cho xã hội theo cách riêng của mình.”</i><br>Chỉ ra lỗi sai trong câu văn trên:", "choices": ["Lỗi thiếu chủ ngữ", "Lỗi dùng từ không cùng hệ quy chiếu", "Lỗi dùng từ không đúng nghĩa", "Lỗi sai logic"], "correctIndex": 1, "explain": "<b>Câu 17 chọn B</b> Giải thích: &quot;Người lao động trí óc&quot; và &quot;người công nhân&quot; không cùng hệ quy chiếu phân loại (một bên theo tính chất lao động, một bên theo ngành nghề/giai tầng), gây khập khiễng trong so sánh."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn phương án chứa từ và cụm từ đúng chính tả", "choices": ["huyên thiên, rủ lòng thương xót, rũ rượi", "huyên thiên, rủ lòng thương sót, rũ rượi", "huyên thiên, rũ lòng thương xót, rủ rượi", "huyên thuyên, rủ lòng thương sót, rũ rượi"], "correctIndex": 0, "explain": "<b>Câu 18 chọn A Giải thích: Các từ viết đúng là: <i>huyên thiên</i>, <i>rủ lòng thương xót</i>, <i>rũ rượi</i>.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Các từ <i>giẫm đạp, chân thật, trốn tránh, hiền lành </i>là:", "choices": ["Từ láy toàn phần", "Từ láy bộ phận", "Từ ghép dựa trên hai từ tố có nghĩa khác nhau", "Từ ghép dựa trên hai từ tố có nghĩa giống nhau."], "correctIndex": 3, "explain": "<b>Câu 19 chọn D</b> Giải thích: Đây là các từ ghép đẳng lập, trong đó các từ tố (giẫm - đạp, chân - thật, trốn - tránh, hiền - lành) có ý nghĩa tương đương hoặc giống nhau."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Dù công ty đang lâm vào cảnh khó khăn, giám đốc vẫn chấp tay rủ áo không đoái hoài.</i><br>Câu trên mắc lỗi gì?", "choices": ["Lỗi dùng từ", "Lỗi ngữ pháp", "Lỗi logic", "Lỗi dấu câu"], "correctIndex": 0, "explain": "<b>Câu 20 chọn A</b> Giải thích: Lỗi dùng từ sai chính tả/thành ngữ: phải là &quot;khoanh tay rủ áo&quot; (hoặc chắp tay), từ &quot;chấp tay&quot; trong ngữ cảnh này bị dùng sai"}], "khongXaoTron": true}, {"noiDungChung": "<b>Dựa vào thông tin dưới đây để trả lời câu hỏi từ câu 21 đến câu 25</b><br><i>Theo ông Củng Diu Pháng, một bậc cao niên ở thôn Củng Chá, dinh thự bằng đá được xây dựng cách đây khoảng một trăm năm, là nơi sinh sống của nhiều thế hệ dòng họ Củng, một dòng họ lớn của dân tộc Pu Péo.</i><br><i>Theo ghi chép, người Pu Péo được xem là cư dân đầu tiên khai phá vùng đất núi non hiểm trở nơi địa đầu Tổ quốc. Dẫu dân số ít, nhưng dân tộc Pu Péo có một nền văn hóa truyền thống rất đa dạng, phong phú, không bị hòa lẫn với các dân tộc khác. Tuy nhiên, cùng với những di biến trong đời sống, nhiều bản sắc văn hóa của dân tộc Pu Péo đang mai một, thậm chí một số nét văn hóa đặc trưng đã biến mất.</i><br><i>“Trước đây người Pu Péo ở nhà sàn, nhưng giờ ở nhà trệt; trang phục truyền thống thì có nhưng chỉ mặc vào lúc lễ hội thôi. Không còn nhiều người nhớ về văn hóa của người Pu Péo nữa đâu, sắp mất cả rồi”, ông Pháng trăn trở.</i><br><i>Cũng như dân tộc Pu Péo, các cộng đồng dân tộc có dân số rất ít người ở nước ta (Brâu, Rơ Măm, Ơ Đu, Si La) đang đối diện nguy cơ “thất truyền” nhiều bản sắc văn hóa truyền thống. Như người Rơ Măm ở Tây Nguyên vốn có truyền thống dệt, may; nhưng hiện nay công cụ dệt may không còn, người biết dệt, may càng hiếm.</i><br><i>Hay người Si La, một cộng đồng dân tộc chỉ còn khoảng 840 nhân khẩu, sinh sống chủ yếu tại Lai Châu và Điện Biên. Trước đây, người Si La sống riêng biệt trên vùng núi cao, ở nhà chôn mái thấp, biết hát dân ca, dân vũ… Từ năm 1972 đến nay, người Si La được bố trí định cư, sống theo làng xóm, cộng đồng dân cư dưới vùng thấp, ở nhà trệt lợp mái tôn và thế hệ trẻ hầu như không biết đến các làn điệu dân ca, dân vũ của dân tộc mình.</i><br><i>Theo kết quả điều tra thực trạng kinh tế-xã hội 53 DTTS thì tỷ lệ hộ đồng bào Si La biết điệu múa truyền thống của dân tộc mình chỉ chiếm 1,3%; tỷ lệ hộ biết sử dụng nhạc cụ truyền thống là 0%; số hộ biết hát bài hát truyền thống là 10%;…</i><br><i>Từ thực tế ấy, việc bảo tồn văn hóa truyền thống của các dân tộc rất ít người cần được nhìn nhận như một nhiệm vụ cấp thiết. Cần bảo vệ không chỉ những công trình vật thể như nhà cổ, dinh thự, công cụ sản xuất, mà cả những giá trị phi vật thể như tiếng nói, lễ hội, dân ca, dân vũ, trang phục, tập quán và tri thức dân gian. Chỉ khi công tác bảo tồn được tiến hành đúng hướng, có chiều sâu và gắn với đời sống thực của cộng đồng, thì những giá trị văn hóa đặc sắc của các dân tộc rất ít người mới có thể được gìn giữ bền vững.</i><br>(Trích Bảo tồn bản sắc văn hóa các dân tộc rất ít người: Chạy đua cùng thời gian; Sỹ Hào)", "cauHoi": [{"question": "Chi tiết nào dưới đây trực tiếp phản ánh sự đứt gãy trong quá trình truyền thừa văn hóa giữa các thế hệ ở người Si La?", "choices": ["Người Si La hiện có quá ít người (840 nhân khẩu).", "Người Si La sống chủ yếu ở Lai Châu và Điện Biên.", "Người Si La chuyển từ nhà chôn mái thấp sang nhà trệt lợp mái tôn.", "Người trẻ Si La hầu như không biết đến các làn điệu dân ca, dân vũ tộc mình."], "correctIndex": 3, "explain": "<b>Câu 21 chọn D</b> Giải thích: Văn bản nêu rõ thế hệ trẻ người Si La &quot;hầu như không biết đến các làn điệu dân ca, dân vũ của dân tộc mình&quot;, đây là sự đứt gãy trực tiếp về truyền thừa."}, {"question": "Cách trình bày thông tin chính của văn bản là:", "choices": ["Đi từ trường hợp cụ thể đến vấn đề khái quát", "Đi từ thực trạng đến giải pháp", "So sánh đối chiếu", "Liệt kê nguyên nhân và nêu giải pháp"], "correctIndex": 0, "explain": "<i class=\"canh-bao-lg\">(Lưu ý: lời giải gốc ghi đáp án B, còn đáp án tô trong đề là A — web đang dùng A.)</i><br><b>Câu 22 chọn B</b> Giải thích: Văn bản đi từ việc nêu thực trạng mai một văn hóa của các dân tộc ít người (Pu Péo, Rơ Măm, Si La) đến việc đề xuất giải pháp bảo tồn cấp thiết."}, {"question": "Việc mở đầu bằng chi tiết về dinh thự đá của dòng họ Củng có tác dụng gì?", "choices": ["Gợi ra một minh chứng cụ thể cho giá trị văn hóa đang cần được gìn giữ.", "Nhấn mạnh vai trò của di tích vật thể trong phát triển du lịch cộng đồng.", "Làm nổi bật vị thế của dòng họ Củng trong cộng đồng Pu Péo.", "Tạo cơ sở để đối chiếu người Pu Péo với người Mông ở Hà Giang."], "correctIndex": 0, "explain": "<b>Câu 23 chọn A</b> Giải thích: Dinh thự đá là một di sản vật thể cụ thể, việc nhắc đến nó giúp gợi ra minh chứng về giá trị văn hóa giàu có cần được bảo vệ"}, {"question": "Từ văn bản, có thể hiểu rằng nguyên nhân chính khiến nhiều giá trị văn hóa truyền thống của các dân tộc thiểu số mai một là gì?", "choices": ["Sự thay đổi điều kiện sống làm thu hẹp môi trường thực hành văn hóa.", "Dân số ít nên khả năng giao lưu văn hóa bị hạn chế.", "Các cộng đồng chưa có ý thức gìn giữ truyền thống của mình.", "Việc định cư ở vùng thấp làm mất hẳn nền tảng văn hóa cũ."], "correctIndex": 0, "explain": "<b>Câu 24 chọn A</b> Giải thích: Văn bản phân tích việc thay đổi điều kiện sống (từ núi cao xuống vùng thấp, thay đổi kiểu nhà ở) đã làm mất đi môi trường thực hành văn hóa truyền thống."}, {"question": "Nhận định nào sau đây <b>không</b> phù hợp với nội dung văn bản?", "choices": ["Mai một văn hóa ở các dân tộc rất ít người thể hiện ở cả phương diện vật thể và phi vật thể.", "Trong lịch sử, người Si La có sự chuyển biến trong nơi ở.", "Có khảo sát không tìm được người Si La biết chơi nhạc cụ dân tộc mình.", "Phục dựng các công trình văn hóa có thể xem là giải pháp thứ yếu đối với việc giữ gìn bản sắc dân tộc."], "correctIndex": 3, "explain": "<b>Câu 25 chọn D</b> Giải thích: Nhận định D không phù hợp vì văn bản nhấn mạnh việc bảo tồn cả vật thể và phi vật thể là nhiệm vụ cấp thiết, không coi việc phục dựng là &quot;thứ yếu&quot;"}], "khongXaoTron": true}, {"noiDungChung": "<b>Dựa vào thông tin dưới đây để trả lời câu hỏi từ câu 26 đến câu 30</b><br><i>“Ai trong chúng ta cũng có những người bạn đang học tập hay làm việc ở nước ngoài. Có &quot;thẻ xanh&quot; đã khó, hành trình để thực sự hòa nhập vào một dân tộc mới còn khó hơn gấp bội. Rất nhiều người trong đó đang bị kẹt ở giữa hai thế giới: họ thấy lạc lõng ở đất nước mới trong khi quê nhà đón họ bằng cái tên xa lạ - Việt kiều. Lòng yêu nước của họ sẽ san sẻ ra sao, khi &quot;yêu nước&quot; từ trước đến nay vẫn là thứ tình cảm độc quyền - chỉ dành cho một và chỉ một nguồn cội.</i><br><i>Người Việt hôm nay vẫn tiếp tục hành trình hướng ra thế giới, túa đi muôn nẻo để học tập, mưu sinh hay tìm kiếm giấc mơ đổi đời. Việt Nam luôn nằm trong nhóm có nhiều sinh viên nhất tại Mỹ, Australia hay Anh. Câu hỏi về dân tộc tính, lòng yêu nước và nguồn cội có lẽ tiếp tục khiến nhiều người mất ngủ. Liệu thế hệ người Việt mới sẽ nghiêng về phía nào, quê hương nơi sinh ra hay quê hương mới?</i><br><i>Chưa bao giờ thành trì &quot;dân tộc tính&quot; và &quot;văn hóa dân tộc&quot; bị lung lay dữ dội như bây giờ. Nhưng có lẽ trong nguy cơ sinh tồn đó, ta mới có dịp nhìn nhận lại tính dân tộc của mình, soi chiếu trong số phận các nền văn hóa khác.</i><br><i>Điều gì khiến hàng triệu người Việt khắp năm châu gọi nhau là đồng bào? Có những thứ không nhất thiết phải gọi tên, định nghĩa, hay quy định chi tiết trong các nghị quyết và văn bản. Bản sắc văn hóa và dân tộc tính cũng vậy. Hàng triệu đồng bào với hàng triệu cách cảm nhận và rung động khác nhau về &quot;tính Việt&quot;, đó sẽ là tấm lưới bảo vệ vững chắc nhất cho văn hóa Việt.</i><br><i>Một nền văn hóa chỉ có thể trường tồn nếu đề cao tính cởi mở và tự do cảm nhận của mỗi cá nhân. Chính sách về văn hóa, vì thế, cần đảm bảo được tự do tư tưởng, thúc đẩy văn hóa và sáng tạo thực sự thì nền văn hóa mới có sức mạnh tập thể để trường tồn. Tức, vai trò của người làm chính sách văn hóa là mở ra chứ không phải đóng khung lại những giá trị, định nghĩa cái gì là có tính dân tộc, cái gì là có văn hóa, cái gì không.</i><br><i>Để nền văn hóa Việt Nam phát triển trong thế giới đa nguyên và nhiều va chạm thì tư duy cởi trói, hạn chế tối đa những vùng cấm, tạo điều kiện để văn hóa được phát triển tự nhiên hơn phải được khuyến khích. Thực tế, trong thời đại toàn cầu hóa, không ai &quot;cấm&quot; được thứ gì. Người ta không khó để tìm xem một bộ phim bị cấm trên mạng. Gần đây nhất, thành công của &quot;làn sóng Hàn Quốc&quot; không phải đến từ cấm đoán mà đến từ sự khuyến khích phát triển và đầu tư sản phẩm văn hóa của đa phần là tư nhân. Không ai phê phán &quot;Ký sinh trùng&quot; được giải Oscar hay &quot;Trò chơi con mực&quot; được hàng trăm triệu người theo dõi là phi Hàn Quốc, dẫu câu chuyện trong phim phê phán những góc tối xã hội rất nặng nề.</i><br><i>Nếu ai cũng được quyền có &quot;tính Việt&quot; theo cảm nhận của mình, văn hóa Việt sẽ có hàng triệu tấm lưới bảo vệ. Toàn cầu hóa khiến các nền văn minh va chạm với nhau và chúng ta đang đứng giữa lựa chọn: cởi mở và thích nghi hay kháng cự lại trong cuộc thánh chiến văn hóa như Don Kihote đánh nhau với cối xay gió.</i><br><i>Nếu còn loay hoay để cố định những giá trị luôn biến thiên theo thời gian, ta sẽ còn kẹt lại trong chiếc lồng tưởng tượng của chính mình.”</i><br>(Trích Tính Việt, Nguyễn Khắc Giang)", "cauHoi": [{"question": "Quan điểm chính của văn bản là gì?", "choices": ["Toàn cầu hóa khiến dân tộc tính của người Việt bị lung lay, đặc biệt ở cộng đồng người Việt sống xa quê.", "Bản sắc văn hóa không nên bị đóng khung cứng nhắc, mà cần được nuôi dưỡng bằng sự cởi mở, tự do cảm nhận và khả năng thích nghi.", "Người Việt ở nước ngoài là lực lượng quan trọng trong việc bảo vệ bản sắc văn hóa dân tộc.", "Văn hóa Việt chỉ có thể trường tồn nếu biết chống lại các ảnh hưởng ngoại lai trong thời đại toàn cầu hóa."], "correctIndex": 1, "explain": "<b>Câu 26 chọn B</b> Giải thích: Tác giả nhấn mạnh bản sắc văn hóa không nên &quot;đóng khung&quot; mà cần cởi mở, tự do và thích nghi để trường tồn."}, {"question": "Việc tác giả nhắc đến những người Việt học tập, làm việc ở nước ngoài nhằm làm rõ điều gì?", "choices": ["Người Việt xa quê thường gặp khó khăn khi hòa nhập với đất nước mới.", "Lòng yêu nước của người Việt ở nước ngoài bị chia tách giữa quê hương cũ và quê hương mới.", "Dân tộc tính hôm nay trở nên phức tạp trong bối cảnh di cư và toàn cầu hóa.", "Cộng đồng Việt kiều cần được nhìn nhận như một bộ phận quan trọng của văn hóa dân tộc."], "correctIndex": 2, "explain": "<b>Câu 27 chọn C</b> Giải thích: Việc nhắc đến người Việt ở nước ngoài nhằm cho thấy dân tộc tính hiện nay không còn cố định mà trở nên đa dạng, phức tạp hơn trong thời đại toàn cầu."}, {"question": "Nhận định nào sau đây không phù hợp với quan điểm của tác giả?", "choices": ["Bản sắc văn hóa cần được bảo vệ bằng cách quy định rõ đâu là có tính dân tộc, đâu là không.", "Mỗi cá nhân có thể có một cách cảm nhận riêng về “tính Việt”.", "Văn hóa muốn trường tồn cần đề cao sự cởi mở và tự do sáng tạo.", "Toàn cầu hóa vừa đặt ra nguy cơ, vừa tạo cơ hội nhìn lại dân tộc tính."], "correctIndex": 0, "explain": "<b>Câu 28 chọn A</b> Giải thích: Tác giả cho rằng bản sắc không nên được quy định cứng nhắc bởi các văn bản hay nghị quyết, nên nhận định A trái ngược với quan điểm tác giả"}, {"question": "Việc nhắc đến “làn sóng Hàn Quốc”, <i>Ký sinh trùng</i> và <i>Trò chơi con mực</i> có tác dụng gì?", "choices": ["Chứng minh văn hóa Hàn Quốc thành công vì biết hạn chế các yếu tố gây tranh cãi.", "Làm rõ rằng văn hóa có thể phát triển mạnh nhờ khuyến khích sáng tạo, đầu tư và cởi mở thay vì cấm đoán.", "Khẳng định các tác phẩm phê phán xã hội thường đại diện tốt nhất cho bản sắc dân tộc.", "Cho thấy Việt Nam cần học Hàn Quốc để xây dựng một mô hình văn hóa đại chúng tương tự."], "correctIndex": 1, "explain": "<b>Câu 29 chọn B</b> Giải thích: Thành công của phim Hàn Quốc là ví dụ cho việc khuyến khích sáng tạo và cởi mở thay vì cấm đoán sẽ giúp văn hóa phát triển."}, {"question": "Hình ảnh “Don Kihote đánh nhau với cối xay gió” trong văn bản nhằm nhấn mạnh điều gì?", "choices": ["Sự dũng cảm của những người kiên trì bảo vệ bản sắc dân tộc trước toàn cầu hóa.", "Tính ảo tưởng, lạc hậu của thái độ cố kháng cự những biến đổi văn hóa.", "Sự bi hài của những cá nhân muốn khôi phục hoàn toàn các giá trị truyền thống đã mất.", "Sự cần thiết phải chiến đấu quyết liệt để giữ gìn văn hóa dân tộc trong thế giới đa nguyên."], "correctIndex": 1, "explain": "<b>Câu 30 chọn B</b> Giải thích: Hình ảnh này ám chỉ việc cố gắng kháng cự lại sự biến đổi tự nhiên của văn hóa trong thời đại mới là một hành động ảo tưởng và lạc hậu"}], "khongXaoTron": true}], "anh": [{"noiDungChung": "<b><i>Câu 31-35: Mark the letter A, B, C, or D on your answer sheet to indicate the correct answer to each of the following questions.</i></b>", "cauHoi": [{"question": "After the argument, she decided to break _____ all communication with her former business partner.", "choices": ["off", "out", "over", "in"], "correctIndex": 0, "explain": "<b>Câu 31 chọn đáp án A. off</b><br><b>Giải thích:</b> Cụm động từ (Phrasal Verb): <b>Break off</b> (something) nghĩa là chấm dứt, cắt đứt (mối quan hệ, sự liên lạc).<br><b>Mẹo:</b> Nhớ cặp &quot;Break off a relationship/communication&quot;."}, {"question": "I _____ this book for weeks, but I still haven’t finished it.", "choices": ["read", "have been reading", "was reading", "am reading"], "correctIndex": 1, "explain": "<b>Câu 32 chọn đáp án B. have been reading</b><br><b>Giải thích:</b> Thì Hiện tại hoàn thành tiếp diễn. Dấu hiệu &quot;for weeks&quot; (khoảng thời gian) và kết quả ở hiện tại &quot;still haven&#x27;t finished&quot; cho thấy hành động đọc sách bắt đầu trong quá khứ, kéo dài liên tục đến hiện tại và còn tiếp diễn.<br><b>Công thức:</b> S + have/has + been + V-ing."}, {"question": "Compared to her previous job, Emily finds her current role _____ rewarding in terms of both salary and personal growth.", "choices": ["as much as", "the most", "so much", "far more"], "correctIndex": 3, "explain": "<b>Câu 33 chọn đáp án D. far more</b><br><b>Giải thích:</b> So sánh hơn với tính từ dài &quot;rewarding&quot;. &quot;Far&quot; là trạng từ dùng để nhấn mạnh mức độ trong câu so sánh hơn (vượt xa, nhiều hơn nhiều).<br><b>Lưu ý:</b> Có thể dùng <i>far, much, a lot</i> đứng trước so sánh hơn để nhấn mạnh."}, {"question": "The journalist was praised for her _____ analysis of the political situation.", "choices": ["deeply", "deepening", "in-depth", "deepen"], "correctIndex": 2, "explain": "<b>Câu 34 chọn đáp án C. in-depth</b><br><b>Giải thích:</b> Từ loại. Cần một tính từ đứng trước danh từ &quot;analysis&quot; để bổ nghĩa. <b>In-depth</b> (adj): chuyên sâu, chi tiết.<br><b>Từ vựng:</b> In-depth analysis = Phân tích chuyên sâu."}, {"question": "The company received _____ of complaints after the defective product was launched,<br>highlighting widespread dissatisfaction.", "choices": ["a huge amount", "a huge number", "too much", "too few."], "correctIndex": 1, "explain": "<b><i>Câu 35 chọn đáp án B. a huge number</i></b><br><b><i>Giải thích:</i></b><i> &quot;Complaints&quot; (lời phàn nàn) là danh từ đếm được số nhiều, nên phải dùng </i><b><i>a number of</i></b><i>. </i><br><b><i>Mẹo:</i></b><i> A number of + N (đếm được); An amount of + N (không đếm được).</i>"}], "khongXaoTron": true}, {"noiDungChung": "<i>Câu 36-40: Mark the letter A, B, C, or D on your answer sheet to indicate the wrong word use/form to each of the following statement.</i>", "cauHoi": [{"question": "John <u>was</u> looking for <u>the</u> stable and <u>well-paid</u> job to support his family <u>financially</u>.", "choices": ["was", "the", "well-paid", "financially"], "correctIndex": 1, "explain": "<b>Câu 36 chọn đáp án B. the</b><br><b>Giải thích:</b> Sửa &quot;the&quot; thành &quot;a&quot;. Khi nhắc đến một công việc chung chung chưa xác định (một công việc ổn định), ta dùng mạo từ bất định &quot;a&quot;."}, {"question": "Neither of the <u>solutions</u> <u>offered</u> by the expert <u>were</u> <u>practical enough</u> to resolve the issue", "choices": ["solutions", "offered", "were", "practical enough."], "correctIndex": 2, "explain": "<b>Câu 37 chọn đáp án C. were</b><br><b>Giải thích:</b> Sửa &quot;were&quot; thành &quot;was&quot;. Chủ ngữ là cấu trúc <b>Neither of + N số nhiều</b>, động từ luôn chia ở số ít.<br><b>Công thức:</b> Neither of / Either of + N (plural) + V (singular)."}, {"question": "<u>The lions</u> cage was <u>designed</u> to look <u>like</u> their natural habitat, <u>with rocks</u>, trees, and a small waterfall.", "choices": ["The lions", "designed", "like", "with rocks."], "correctIndex": 0, "explain": "<b>Câu 38 chọn đáp án A. The lions</b><br><b>Giải thích:</b> Sửa thành &quot;The lions&#x27; &quot; (thêm dấu phẩy sau chữ s). Đây là sở hữu cách của danh từ số nhiều kết thúc bằng &#x27;s&#x27; (Cái chuồng của những con sư tử)."}, {"question": "Emma <u>told</u> me she <u>would</u> need to finish <u>his project</u> by Friday to <u>meet the deadline</u>.", "choices": ["told", "would", "his project", "meet the deadline"], "correctIndex": 2, "explain": "<b>Câu 39 chọn đáp án C. his project</b><br><b>Giải thích:</b> Lỗi hòa hợp đại từ. Chủ ngữ là &quot;Emma&quot; (nữ), nên tính từ sở hữu phải là &quot;her project&quot; thay vì &quot;his&quot;."}, {"question": "he project whose <u>its aim</u> was <u>to reduce</u> carbon emissions has been <u>highly praised</u> by environmental <u>organizations</u>.", "choices": ["its aim", "to reduce", "highly praised", "orgainizations."], "correctIndex": 0, "explain": "<b>Câu 40 chọn đáp án A. its aim</b><br><b>Giải thích:</b> Lỗi thừa từ. &quot;Whose&quot; là đại từ quan hệ thay thế cho tính từ sở hữu, nên không dùng thêm &quot;its&quot; nữa. Sửa thành: &quot;The project <b>whose aim</b> was...&quot;."}], "khongXaoTron": true}, {"noiDungChung": "<b><i>Câu 41-45: Which of the following best restates each of the given sentences?</i></b>", "cauHoi": [{"question": "Sarah said, “Mark, don’t forget to submit the report by Monday.”", "choices": ["Sarah reminded Mark to not forget to submit the report by Monday.", "Sarah reminded Mark to submit the report by Monday.", "Sarah said to Mark that he should submit his report the next day.", "Sarah warned Mark to submit the report on Monday."], "correctIndex": 1, "explain": "<b>Câu 41 chọn đáp án B. Sarah reminded Mark to submit the report by Monday.</b><br><b>Giải thích:</b> Cấu trúc câu tường thuật với lời nhắc nhở: <b>S + reminded + O + to-V</b>. &quot;Don&#x27;t forget to...&quot; chính là một lời nhắc nhở."}, {"question": "If Alice had taken the earlier bus, she would have arrived on time.", "choices": ["Alice missed the earlier bus, so she didn’t arrive on time.", "Alice would arrive on time if she had taken the earlier bus.", "Alice took the earlier bus, and she arrived on time.", "Alice could have arrived on time if she took the earlier bus."], "correctIndex": 0, "explain": "<b>Câu 42 chọn đáp án A. Alice missed the earlier bus, so she didn&#x27;t arrive on time.</b><br><b>Giải thích:</b> Câu gốc là điều kiện loại 3 (trái với quá khứ). Nghĩa là thực tế trong quá khứ Alice đã lỡ xe buýt và đã không đến đúng giờ."}, {"question": "Among the three paintings, the second one has the most vibrant colors.", "choices": ["The first painting is more vibrant than the second one.", "The first and third paintings aren’t as vibrant as the second painting.", "The third painting has the most subtle colors of all.", "None of the paintings are vibrant enough."], "correctIndex": 1, "explain": "<b>Câu 43 chọn đáp án B. The first and third paintings aren&#x27;t as vibrant as the second painting.</b><br><b>Giải thích:</b> Câu gốc nói bức thứ 2 rực rỡ nhất trong 3 bức. Đáp án B dùng so sánh không bằng để diễn đạt tương đương: bức 1 và 3 không rực rỡ bằng bức 2."}, {"question": "People believe that the scientist discovered the cure by accident.", "choices": ["It was believed that the scientist had discovered the cure by accident.", "The cure was believed to have been discovered by accident by the scientist.", "The scientist is believed to have discovered the cure by accident.", "The cure was discovered by accident, people believed."], "correctIndex": 2, "explain": "<b>Câu 44 chọn đáp án C. The scientist is believed to have discovered the cure by accident.</b><br><b>Giải thích:</b> Câu bị động đặc biệt (Passive voice with reporting verbs). Vì hành động &quot;discovered&quot; xảy ra trước hành động &quot;believe&quot; nên dùng <b>to have + V3/ed</b>."}, {"question": "The city’s air quality has worsened significantly in recent years, likely because of increased traffic.", "choices": ["Heavier traffic has caused the air quality in the city to worsen.", "The city’s declining air quality may be linked to an increase in traffic.", "The air quality in the city is improving due to reduced traffic levels.", "Decreased traffic has led to better air quality in the city."], "correctIndex": 1, "explain": "<b>Câu 45 chọn đáp án B. The city&#x27;s declining air quality may be linked to an increase in traffic.</b><br><b>Giải thích:</b> Câu gốc nói chất lượng không khí tệ đi &quot;có thể do&quot; (likely because of) tăng phương tiện. Đáp án B dùng &quot;may be linked to&quot; (có thể liên quan tới) sát nghĩa nhất"}], "khongXaoTron": true}, {"noiDungChung": "<b><i>Câu 46-52: Read the passage carefully and choose an option (A, B, C, or D) that best answers each question. Choose an option (A, B, C, or D) that best answers each question.</i></b><br>1. The world of presidential elections has been going through some big changes lately. It is not<br>like it used to be, and that is a positive change. Taking a close look at how elections are evolving<br>will enable us to understand the current transformations.<br><b>2.</b> Presidential elections are no longer confined to traditional campaigns. It is like an open arena where everyone’s voice can be heard. Candidates from diverse backgrounds are entering the political scene, each with unique perspectives and strategies. Some focus on solving economic challenges, while <b>others</b> emphasize social unity and global leadership. This mix of priorities is what makes elections so engaging today.<br><b>3.</b> Candidates also pay close attention to pressing social issues, such as equality, healthcare, and climate change. They use debates, rallies, and interviews to discuss critical matters affecting citizens. When major movements like environmental sustainability <b>gain momentum</b>, many candidates highlight their plans to address these concerns. They aim to create a future where fairness and opportunity are accessible to all.<br><b>4.</b> Media plays a significant role in modern elections, just like fashion does in pop culture. Candidates carefully curate their image through televised events, posters, and social media. Their appearance and mannerisms are analyzed, and even small details can become topics of discussion. Beyond mere presentation, it’s about showing leadership, relatability, and trustworthiness to thepublic.<br><b>5.</b> Social media platforms, such as Twitter, Instagram, and Facebook, have become game- changers for elections. Candidates use these tools to connect directly with voters, sharing their ideas and responding to issues in real time. It is like having a conversation with future leaders, allowing voters to stay informed and involved.<br><b>6.</b> While there are still challenges, such as misinformation and political polarization, the modern presidential election cannot be denied its influence. If citizens approach campaigns with open minds, they can see that elections are a vital process that empowers people, fosters change, and shapes a nation’s future.", "cauHoi": [{"question": "What is the passage mainly about?", "choices": ["How elections have become less significant over time", "Positive changes in modern presidential elections", "Challenges facing today’s election campaigns", "The role of media in influencing voters’ opinions"], "correctIndex": 1, "explain": "<b>Câu 46 chọn B:</b> Bài viết nói về những thay đổi tích cực trong bầu cử hiện đại."}, {"question": "According to paragraph 2, what does the word &quot;<b>others</b>&quot; refer to?", "choices": ["Candidates", "Priorities", "Challenges", "Perspectives."], "correctIndex": 0, "explain": "<b>Câu 47 chọn A:</b> &quot;others&quot; thay thế cho &quot;candidates&quot; ở câu trước đó."}, {"question": "In paragraph 2, which of the following is NOT a feature of presidential elections today?", "choices": ["They include candidates from different backgrounds.", "They highlight distinctive tactics and policies.", "They focus solely on conventional campaign methods.", "They address issues like social unity and the economy."], "correctIndex": 2, "explain": "<b>Câu 48 chọn C:</b> Bài viết nói bầu cử không còn bó hẹp trong phương pháp truyền thống."}, {"question": "In paragraph 3, what is the word &quot; <b>gain</b> <b>momentum</b>&quot; closest in meaning to?", "choices": ["become popular", "lose focus", "face challenges", "slow down"], "correctIndex": 0, "explain": "<b>Câu 49 chọn A:</b> &quot;Gain momentum&quot; = trở nên mạnh mẽ/phổ biến hơn (become popular).<br><b>Câu 49 chọn A:</b> &quot;Gain momentum&quot; = trở nên mạnh mẽ/phổ biến hơn (become popular)."}, {"question": "In paragraph 4, why is media compared to fashion in elections?", "choices": ["It helps shape the candidates’ public image.", "It promotes new political fashion trends.", "It analyzes candidates’ personalities deeply.", "It focuses on candidates’ clothing and style."], "correctIndex": 0, "explain": "<b>Câu 50 chọn A:</b> So sánh để nói về việc xây dựng hình ảnh công chúng."}, {"question": "In paragraph 5, what can be inferred about social media’s role in elections?", "choices": ["It allows candidates to share ideas with the public directly.", "It distracts voters from traditional campaign messages.", "It has replaced in-person rallies and debates completely.", "It weakens voter interest in current political events."], "correctIndex": 0, "explain": "<b>Câu 51 chọn A:</b> MXH giúp ứng viên kết nối trực tiếp với cử tri."}, {"question": "According to paragraph 6, which of the following is a challenge of modern elections?", "choices": ["Political unity", "Candidate diversity", "Distortion of information", "Limited voter involvement"], "correctIndex": 2, "explain": "<b>Câu 52 chọn C: Thách thức được nhắc tới là &quot;misinformation&quot; (xuyên tạc thông tin).</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 53-60</b>: <b>Read the passage carefully and Choose an option (A, B, C, or D) that best answers each question.</b><br><b>1.</b> Taylor Swift’s rise from country music’s rising star to a global pop icon has been nothing short of extraordinary. Over the past two decades, Swift has redefined what it means to be a versatile artist, seamlessly transitioning across genres while maintaining her authenticity. Her ability to tell stories through music resonates deeply with millions of fans worldwide, making her not just a performer but a cultural force.<br><b>2.</b> Swift’s songwriting stands out as her most defining strength. Through detailed storytelling, she paints vivid pictures of love, heartbreak, and personal growth, often using her own life experiences as inspiration. Albums like Fearless and 1989 capture the emotions of youth, while folklore and evermore showcase her shift to introspective, poetic narratives. These diverse themes allow listeners to see <b>themselves</b> in her music, creating an emotional connection that transcends age and geography.<br><b>3.</b> Beyond her artistry, Taylor Swift has demonstrated an uncanny ability to navigate the changing music industry. From confronting record labels over artist rights to embracing streaming platforms, Swift’s decisions have shaped discussions around intellectual property and fair compensation for musicians. Her public re-recording of earlier albums, known as “Taylor’s Version,” has not only reclaimed ownership of her work but also sparked admiration for her resilience and business <b>acumen</b>.<br><b>4.</b> Swift’s influence extends far beyond music. She uses her platform to address significant social issues, including gender equality, LGBTQ+ rights, and voter engagement. By speaking openly on topics that matter, she has inspired millions of fans to take action. Swift’s endorsement of political candidates, for instance, has been credited with increasing youth voter registration in the United States.<br><b>5. </b>While critics often question the intense media scrutiny surrounding her personal life, Swift’s enduring success speaks volumes about her talent and determination. Whether selling out stadiums on her record-breaking Eras Tour or breaking streaming records, she continues to set new standards for artistry and cultural impact. Taylor Swift’s journey reminds us that creativity, perseverance, and purpose are powerful forces capable of shaping not only music but also society as a whole.", "cauHoi": [{"question": "The best title of the passage can be _____.", "choices": ["Taylor Swift: A Master of Songwriting and Business", "Taylor Swift’s Role in Social and Political Movements", "Taylor Swift: From Music to Cultural and Social Impacts", "How Taylor Swift Reinvented the Music Industry"], "correctIndex": 2, "explain": "<b>Câu 53 chọn C: Tiêu đề bao quát cả âm nhạc và tầm ảnh hưởng xã hội</b>"}, {"question": "The word <b>“themselves”</b> in paragraph 2 refers to _____.", "choices": ["diverse themes", "listeners", "Taylor Swift and listeners", "emotions of youth"], "correctIndex": 1, "explain": "<b>Câu 54 chọn B: &quot;Themselves&quot; thay thế cho &quot;listeners&quot; (người nghe thấy mình trong âm nhạc)</b>"}, {"question": "According to paragraph 2, Swift’s albums like folklore and evermore are described as _____.", "choices": ["focused on youthful energy and ambition", "works with lyrical beauty and deeper, reflective themes", "mostly inspired by traditional country music sounds", "highlighting her experiences of global tours she has done before"], "correctIndex": 1, "explain": "<b>Câu 55 chọn B:</b> Hai album này mang tính nội tâm và thơ ca (reflective themes)."}, {"question": "In paragraph 3, what does the word &quot;<b>acumen</b>&quot; mean?", "choices": ["intelligence", "creativity", "experience", "confidence"], "correctIndex": 0, "explain": "<b>Câu 56 chọn A:</b> &quot;Acumen&quot; = sự nhạy bén, thông minh (intelligence/sharpness)."}, {"question": "What does the author suggest about Taylor Swift’s re-recording of her albums?", "choices": ["It proved her loyalty to the music industry.", "It showcased her ability to inspire respect and support.", "It weakened her relationship with major record labels.", "It only targeted her most devoted fans"], "correctIndex": 1, "explain": "<b>Câu 57 chọn B:</b> Việc thu âm lại cho thấy sự kiên cường và khơi gợi sự ngưỡng mộ/ủng hộ."}, {"question": "In paragraph 4, Swift’s social involvement shows that _____.", "choices": ["she focuses more on music than activism", "her influence encourages real social change", "she endorses only causes that benefit her career", "her fans disagree with her political endorsements"], "correctIndex": 1, "explain": "<b>Câu 58 chọn B:</b> Tầm ảnh hưởng của cô khuyến khích những thay đổi xã hội thực sự (như đăng ký cử tri)."}, {"question": "It can be inferred from paragraph 5 that Swift’s career success _____.", "choices": ["is mainly due to her early start in country music", "has been unaffected by criticism and media scrutiny", "results from her creativity, resilience, and influence", "is tied to her record-breaking tours alone"], "correctIndex": 2, "explain": "<b>Câu 59 chọn C:</b> Thành công đến từ sự sáng tạo, kiên cường và tầm ảnh hưởng."}, {"question": "According to the passage, what makes Taylor Swift remarkable?", "choices": ["Her ability to challenge norms in the music industry.", "Her work solely in storytelling through music.", "Her exclusive focus on pop music success.", "Her refusal to address modern societal issues."], "correctIndex": 0, "explain": "<b><i>Câu 60 chọn A: Cô đáng chú ý vì khả năng thách thức các quy chuẩn ngành âm nhạc (quyền sở hữu tác phẩm).</i></b>"}], "khongXaoTron": true}], "kh": [{"noiDungChung": "<b>MÔN HOÁ - Dựa vào thông tin dưới đây để trả lời các Câu từ 103 đến 105 </b><br>Các chất có khuynh hướng tách khỏi bề mặt của chất lỏng để chuyển thành trạng thái hơi và gây áp suất hơi. Khi tốc độ bay hơi bằng tốc độ ngưng tụ thì áp suất hơi lúc đó gọi là áp suất hơi bão hòa. Áp suất hơi bão hòa tỷ lệ thuận với nhiệt độ. Ở nhiệt độ mà áp suất hơi bão hòa bằng áp suất khí quyển thì nhiệt độ đó chính là nhiệt độ sôi của chất lỏng. Biết áp suất hơi bão hòa của hỗn hợp hơi bằng tổng áp suất hơi bão hòa riêng phần của các chất trong hỗn hợp.<br>Cho bảng số liệu:<br><table class=\"bang-de\"><tr><td>Hỗn hợp</td><td>n-heptane (mol)</td><td>n-octane (mol)</td><td>Áp suất hơi bão hòa của hỗn hợp ở \\(\\mathbf{25}^{\\mathbf{\\circ}}\\mathbf{C}\\) (mmHg)</td></tr><tr><td>1</td><td>0,0</td><td>1,0</td><td>14,0</td></tr><tr><td>2</td><td>0,2</td><td>0,8</td><td>20,4</td></tr><tr><td>3</td><td>0,4</td><td>0,6</td><td>26,8</td></tr><tr><td>4</td><td>0,5</td><td>0,5</td><td>30,0</td></tr><tr><td>5</td><td>0,6</td><td>0,4</td><td>33,2</td></tr><tr><td>6</td><td>0,8</td><td>0,2</td><td>39,6</td></tr><tr><td>7</td><td>1,0</td><td>0,0</td><td>46,0</td></tr></table>", "cauHoi": [{"question": "Ở 25°C, một dung dịch có mol n-heptane nằm trong khoảng từ 0,6 đến 0,8. Áp suất hơi bão hòa của hỗn hợp có giá trị nào sau đây?", "choices": ["26,8 – 30,0", "30,0 – 33,2", "33,2 – 39,6", "20,4 – 26,8"], "correctIndex": 2, "explain": "<b>Đáp án: C</b>"}, {"question": "Nhận định nào sau đây <b>không đúng</b>?", "choices": ["Khi tăng phần mol n-octane thì áp suất hơi bão hòa của hỗn hợp giảm.", "Áp suất hơi riêng phần của mỗi chất trong hỗn hợp luôn nhỏ hơn áp suất hơi bão hòa của chất đó ở trạng thái tinh khiết.", "Khi x<sub>heptane</sub> = 0,5 (mol) thì áp suất hơi riêng phần của hai chất bằng nhau.", "Áp suất hơi bão hòa của hỗn hợp là tổng áp suất hơi riêng phần của các cấu tử."], "correctIndex": 2, "explain": "<b>Đáp án: C</b><br>P<sub>heptane</sub> = 0,5.46 = 23<br>P<sub>octane</sub> = 0,5.14 = 7"}, {"question": "Xét hai dung dịch lý tưởng ở 25°C:<br><b>Dung dịch X</b> có số mol của n-heptane<sub> </sub>là 0,4 mol<br><b>Dung dịch Y</b> có số mol của n-heptane<sub> </sub>là 0,7 mol<br>Cho các nhận định sau đây:<br><b>(1).</b> Áp suất hơi bão hòa của dung dịch Y lớn hơn dung dịch X.<br><b>(2).</b> Áp suất hơi riêng phần của n-octane trong dung dịch X lớn hơn trong dung dịch Y.<br><b>(3).</b> Ở áp suất khí quyển 760 mmHg, dung dịch X có nhiệt độ sôi cao hơn dung dịch Y.<br><b>(4).</b> Tổng áp suất hơi của hai dung dịch là như nhau vì cùng nhiệt độ.<br>Số phát biểu đúng là:", "choices": ["1", "2", "3", "4"], "correctIndex": 2, "explain": "<b>Đáp án: C (1, 2, 3).</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN LÝ - Dựa vào thông tin dưới đây để trả lời các Câu từ 106 đến 108 </b><br>Một trong những ứng dụng quan trọng của dòng điện xoay chiều chính là khả năng truyền tải ở cự ly xa với sự hao phí truyền tải trên đường dây thấp, bằng cách nâng điện áp trước khi truyền tải. Với một mô hình truyền tải lý tưởng, khi nâng điện áp tại nguồn lên k lần, công suất hao phí trên đường dây sẽ giảm đi \\(k^{2}\\) lần. Theo định luật Joule-Lenz, công suất hao phí do tỏa nhiệt trên đường dây (<img class=\"anh-de\" src=\"data/anh/l15/6a7f1da06ec146f7.png\" alt=\"\" style=\"width:23px;height:24px;vertical-align:middle\">) được xác định bởi công thức:<img class=\"anh-de\" src=\"data/anh/l15/88abe2e38fc456bc.png\" alt=\"\" style=\"width:159px;height:47px;vertical-align:middle\"><br>Trong đó <img class=\"anh-de\" src=\"data/anh/l15/0c4b735c79e97595.png\" alt=\"\" style=\"width:16px;height:18px;vertical-align:middle\"> là công suất truyền đi, <img class=\"anh-de\" src=\"data/anh/l15/679851591b2bf36d.png\" alt=\"\" style=\"width:18px;height:18px;vertical-align:middle\"> là điện áp tại nơi truyền đi, <img class=\"anh-de\" src=\"data/anh/l15/cd735690173d395d.png\" alt=\"\" style=\"width:16px;height:18px;vertical-align:middle\"> là điện trở đường dây và <img class=\"anh-de\" src=\"data/anh/l15/7f2e5cb4d37a2f1a.png\" alt=\"\" style=\"width:38px;height:18px;vertical-align:middle\"> là hệ số công suất (trong điều kiện lý tưởng, <img class=\"anh-de\" src=\"data/anh/l15/4e6b70fb13a85c40.png\" alt=\"\" style=\"width:58px;height:21px;vertical-align:middle\">).<br>Tại Việt Nam, đường dây siêu cao áp 500 kV Bắc – Nam (mạch 1 khánh thành ngày 27/5/1994) đóng vai trò xương sống cho hệ thống điện quốc gia. Để giảm hao phí, điện áp được nâng lên mức 500 kV tại trạm phát và sau đó qua nhiều cấp hạ áp (220 kV, 110 kV, 22kV) trước khi đến người dùng ở mức 220 V. Việc thay đổi điện áp này được thực hiện bởi máy biến áp dựa trên hiện tượng cảm ứng điện từ. Một máy biến áp lý tưởng có mối liên hệ giữa điện áp (<img class=\"anh-de\" src=\"data/anh/l15/d01bd7e2ea8d8a4c.png\" alt=\"\" style=\"width:18px;height:18px;vertical-align:middle\">) tỉ lệ với số vòng dây (<img class=\"anh-de\" src=\"data/anh/l15/0e984d0a0678d59d.png\" alt=\"\" style=\"width:18px;height:18px;vertical-align:middle\">)<br>Giả sử một hệ thống truyền tải lý tưởng đang vận hành với điện áp nguồn <img class=\"anh-de\" src=\"data/anh/l15/9d96f87862ed82aa.png\" alt=\"\" style=\"width:85px;height:24px;vertical-align:middle\"> và hiệu suất truyền tải đạt <img class=\"anh-de\" src=\"data/anh/l15/66079267cb221eaf.png\" alt=\"\" style=\"width:58px;height:21px;vertical-align:middle\">.", "cauHoi": [{"question": "Nếu giảm giá trị điện áp tại nguồn xuống 450 kV, công suất hao phí trên đường dây sẽ thay đổi xấp xỉ?", "choices": ["Tăng 1,23%", "Tăng 23%", "Tăng 1,1%", "Giảm 19%"], "correctIndex": 1, "explain": "HD:<br><img class=\"anh-de\" src=\"data/anh/l15/68c498e668913c34.png\" alt=\"\" style=\"width:210px;height:55px;vertical-align:middle\"> <img class=\"anh-de\" src=\"data/anh/l15/738b896176d7870f.png\" alt=\"\" style=\"width:20px;height:16px;vertical-align:middle\"> Tăng thêm 23% <img class=\"anh-de\" src=\"data/anh/l15/738b896176d7870f.png\" alt=\"\" style=\"width:20px;height:16px;vertical-align:middle\"><b>Chọn B</b>"}, {"question": "Nếu tăng điện áp tại nguồn lên đến 550 kV, thì hiệu suất truyền tải xấp xỉ là", "choices": ["90%", "87%", "85%", "95%"], "correctIndex": 2, "explain": "<b>HD: </b><img class=\"anh-de\" src=\"data/anh/l15/123c889e765b2b16.png\" alt=\"\" style=\"width:332px;height:55px\"><img class=\"anh-de\" src=\"data/anh/l15/738b896176d7870f.png\" alt=\"\" style=\"width:20px;height:16px;vertical-align:middle\"><b>Chọn C</b>"}, {"question": "<b>Cho các phát biểu sau đây về hệ thống truyền tải và máy biến áp:</b><br>(1) Để giảm công suất hao phí truyền tải k lần, thì phải tăng hiệu điện thế trước khi truyền tải \\(\\sqrt{k}\\) lần<br>(2) Máy biến áp có thể thay đổi điện áp của dòng điện không đổi nếu số vòng dây cuộn thứ cấp lớn hơn sơ cấp.<br>(3) Hiệu suất truyền tải điện năng tỉ lệ nghịch với bình phương điện áp truyền tải.<br>(4) Trong quá trình hạ áp để đưa điện vào khu dân cư, cuộn sơ cấp của máy biến áp có số vòng dây ít hơn cuộn thứ cấp.<br>(5) Đường dây 500 kV giúp giảm hao phí truyền tải hơn khoảng 5,16 triệu lần so với nếu dùng điện áp 220 V để truyền đi cùng một công suất.<br><b>Số phát biểu KHÔNG ĐÚNG là:</b>", "choices": ["2.", "3.", "4.", "1."], "correctIndex": 1, "explain": "(1) Đúng.<br>(2) Sai: Máy biến áp không hoạt động với dòng điện một chiều không đổi.<br>(3) Sai: Hiệu suất <img class=\"anh-de\" src=\"data/anh/l15/e3e7367c7527155b.png\" alt=\"\" style=\"width:83px;height:42px;vertical-align:middle\"> không phải tỉ lệ thuận đơn thuần với <img class=\"anh-de\" src=\"data/anh/l15/7bf518b9f425ceeb.png\" alt=\"\" style=\"width:23px;height:21px;vertical-align:middle\"> (đây là hàm bậc phân thức).<br>(4) Sai: Hạ áp thì <img class=\"anh-de\" src=\"data/anh/l15/9f44214fbaaa36e2.png\" alt=\"\" style=\"width:145px;height:24px;vertical-align:middle\"> (sơ cấp phải nhiều vòng hơn thứ cấp).<br>(5) Đúng: <img class=\"anh-de\" src=\"data/anh/l15/40c103dfec4e796f.png\" alt=\"\" style=\"width:156px;height:42px;vertical-align:middle\">.<br>Số phát biểu sai: 3 (phát biểu 2, 3, 4). Chọn B."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SINH - Dựa vào thông tin dưới đây để trả lời các Câu từ 109 đến 111</b><br>Trong quần xã sinh vật, sự phân bố của các loài được xác định bởi ổ sinh thái – không gian biểu hiện cách sinh sống và giới hạn chịu đựng của loài đối với các nhân tố môi trường. Tại cùng một nơi ở, các loài có thể thiết lập các mối quan hệ đa dạng để sinh tồn. Qua quan sát thực địa về sự tương tác giữa loài A và loài B, các chuyên gia ghi nhận các đặc điểm sau:<br><b>Sự giao thoa nguồn sống:</b> Tại thời điểm 1, các chỉ số về dinh dưỡng và không gian cho thấy sự trùng lặp đáng kể (vùng màu xanh lá trong biểu đồ).<br><b>Các mối quan hệ tiềm năng trong quần xã:</b> Một hệ sinh thái ổn định thường bao gồm nhiều hình thức tương tác như:<br>1. <b>Cộng sinh:</b> Hai bên cùng có lợi và bắt buộc phải có nhau.<br>2. <b>Cạnh tranh:</b> Các loài tranh giành nguồn sống giới hạn, dẫn đến kìm hãm sự phát triển của nhau.<br>3. <b>Vật ăn thịt – con mồi:</b> Loài này sử dụng loài kia làm thức ăn.<br>4. <b>Ức chế - cảm nhiễm:</b> Một loài vô tình gây hại cho loài khác thông qua chất tiết hoặc hoạt động sống.<br><b>Sự phân hóa:</b> Tại thời điểm 2, biểu đồ cho thấy hai loài đã có sự tách biệt về ổ sinh thái nhằm giảm bớt áp lực tương tác trực tiếp, giúp cả hai cùng tồn tại trong cùng một nơi ở.<br>Ổ sinh thái là không gian sinh thái, bao gồm tất cả các giới hạn về các nhân tố sinh thái mà ở đó, đảm bảo cho loài tồn tại và phát triển theo thời gian. Người ta phân biệt ổ sinh thái và nơi ở: Ổ sinh thái biểu hiện cách sinh sống của loài; còn nơi ở là nơi cư trú của loài. Trong một nơi ở có thể có nhiều ổ sinh thái khác nhau, do đó sẽ có nhiều loài khác nhau cùng chung sống.<br>Các loài sống chung trong một môi trường thì thường có ổ sinh thái trùng nhau một phần. Ví dụ ổ sinh thái của 2 loài A và B được mô tả ở 2 thời điểm khác nhau", "cauHoi": [{"question": "Mối quan hệ giữa 2 loài A và B là", "choices": ["Ức chế - cảm nhiễm", "Cạnh tranh", "Vật ăn thịt – con mồi", "Cộng sinh"], "correctIndex": 1, "explain": "<b>Câu 109: Chọn B - Cạnh tranh</b><br>Nhìn vào hình, ở Thời điểm 1, hai loài A và B có phần diện tích đè lên nhau (vùng xanh). Khi hai loài cùng giành nhau một &quot;miếng bánh&quot; (nguồn sống), chúng chắc chắn sẽ <b>Cạnh tranh</b>.<br><b>Kết quả:</b> Sang Thời điểm 2, chúng tự tách nhau ra để giữ hòa bình (tiến hóa phân hóa ổ sinh thái)."}, {"question": "Khi nói về ổ sinh thái, phát biểu nào sau đây là <b>sai</b>?", "choices": ["Hai loài có ổ sinh thái khác nhau thì không cạnh tranh với nhau.", "Cùng một nơi ở thường chỉ có một ổ sinh thái.", "Kích thước thức ăn, loại thức ăn của mỗi loài tạo nên ổ sinh thái về dinh dưỡng của loài đó.", "Cùng một nơi ở, hai loài có ổ sinh thái giao nhau càng lớn, sự cạnh tranh giữa chúng càng gay gắt."], "correctIndex": 1, "explain": "<b>Câu 110: Chọn B - Sai</b><br>Trong một khu rừng (nơi ở), có loài chim ăn sâu trên ngọn cây, có loài chuột ăn rễ cây dưới đất. Một nơi ở có <b>rất nhiều</b> ổ sinh thái khác nhau. Nếu chỉ có một ổ sinh thái, các loài sẽ đánh nhau đến chết và chỉ còn một loài duy nhất tồn tại."}, {"question": "Nếu ổ sinh thái của 2 loài trùng nhau càng nhiều thì", "choices": ["Ổ sinh thái của mỗi loài được mở rộng", "Hỗ trợ nhau tốt hơn chống lại điều kiện bất lợi của môi trường", "Mức độ cạnh tranh càng gay gắt", "Hai loài này sẽ tiến hóa thành 1 loài"], "correctIndex": 2, "explain": "<b>Câu 111: Chọn C - Mức độ cạnh tranh càng gay gắt</b><br><b>Quy luật:</b> Trùng nhau càng nhiều = Giành nhau càng nhiều = Đánh nhau càng hăng.<br>Nó giống như việc hai cửa hàng cùng bán một mặt hàng trên cùng một con phố, sự cạnh tranh sẽ cao hơn nhiều so với việc mỗi hàng bán một thứ khác nhau."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN ĐỊA - Dựa vào thông tin dưới đây để trả lời các Câu từ 112 đến 114 </b><br>An ninh nguồn nước được hiểu là sự bảo đảm về số lượng nước, chất lượng nước để phục vụ cho sức khỏe, sinh kế, hoạt động sản xuất và môi trường sinh thái. Trong giai đoạn hiện nay, Việt Nam đang đối mặt với những thách thức nghiêm trọng về an ninh nguồn nước do tác động kép từ biến đổi khí hậu và các hoạt động khai thác kinh tế của con người.<br>Số liệu thống kê cho thấy tổng lượng nước mặt trung bình năm của Việt Nam khoảng 830 – 840 tỉ $m^3$. Tuy nhiên, có tới 60% lượng nước này được sản sinh từ lưu vực các sông nằm ngoài lãnh thổ. Điều này khiến Việt Nam trở thành quốc gia phụ thuộc lớn vào nguồn nước xuyên biên giới. Ở khu vực Đồng bằng sông Cửu Long, việc xây dựng các đập thủy điện ở thượng nguồn cùng với hiện tượng nước biển dâng đã làm trầm trọng thêm tình trạng xâm nhập mặn, gây ảnh hưởng trực tiếp đến sản xuất nông nghiệp và nước sinh hoạt của hàng triệu người dân.<br>Bên cạnh đó, biến đổi khí hậu làm thay đổi quy luật của chu trình tuần hoàn nước, khiến lượng mưa phân bố không đều giữa các mùa và các vùng. Tình trạng hạn hán kéo dài ở miền Trung và Tây Nguyên, kết hợp với lũ lụt bất thường ở các đô thị lớn, cho thấy sự mong manh của hệ thống quản trị tài nguyên nước hiện tại. Để giải quyết vấn đề này, việc chuyển đổi sang mô hình kinh tế tuần hoàn nước và tăng cường hợp tác quốc tế trong quản lý lưu vực sông liên quốc gia là những giải pháp cấp bách.", "cauHoi": [{"question": "Dựa vào bài đọc, yếu tố nào sau đây là nguyên nhân chính khiến an ninh nguồn nước của Việt Nam có tính tự chủ thấp?", "choices": ["Do lượng mưa trung bình năm của Việt Nam quá thấp.", "Do phần lớn tổng lượng nước mặt phụ thuộc vào các lưu vực sông ngoài lãnh thổ.", "Do hệ thống đập thủy điện trong nước điều tiết nước không hiệu quả.", "Do tốc độ đô thị hóa nhanh làm cạn kiệt các mạch nước ngầm."], "correctIndex": 1, "explain": "Chọn đáp án B<br>Bài đọc nêu rõ: &quot;60% lượng nước này được sản sinh từ lưu vực các sông nằm ngoài lãnh thổ&quot;."}, {"question": "Tại Đồng bằng sông Cửu Long, sự kết hợp giữa các đập thủy điện thượng nguồn và nước biển dâng gây ra hệ quả trực tiếp nào?", "choices": ["Làm thay đổi hoàn toàn chu trình tuần hoàn nước tự nhiên.", "Làm gia tăng diện tích rừng ngập mặn ở các cửa sông.", "Gây ra tình trạng xâm nhập mặn sâu và thiếu nước ngọt cho sản xuất.", "Làm tăng lượng phù sa bồi đắp cho đồng bằng hàng năm."], "correctIndex": 2, "explain": "<b>Chọn đáp án</b> <b>C. </b><br><b>Bài đọc đề cập trực tiếp đến việc các yếu tố này làm &quot;trầm trọng thêm tình trạng xâm nhập mặn&quot;.</b>"}, {"question": "Theo nội dung bài đọc, giải pháp mang tính chiến lược và lâu dài để bảo vệ an ninh nguồn nước là gì?", "choices": ["Ngừng hoàn toàn việc canh tác nông nghiệp tại các vùng thiếu nước.", "Xây dựng thêm nhiều hồ chứa nước quy mô lớn tại tất cả các tỉnh thành.", "Chỉ tập trung vào việc xử lý nước thải sinh hoạt tại các đô thị lớn.", "Hợp tác quốc tế quản lý sông xuyên biên giới và áp dụng kinh tế tuần hoàn nước."], "correctIndex": 3, "explain": "<b>Chọn đáp án D</b><br><b>Đây là thông tin nằm ở đoạn cuối bài: &quot;tăng cường hợp tác quốc tế... và kinh tế tuần hoàn nước là giải pháp cấp bách&quot;.</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SỬ - Dựa vào thông tin dưới đây để trả lời các Câu từ 115 đến 117 </b><br>&quot;Sau Chiến tranh thế giới thứ hai, bản đồ chính trị thế giới đã có những thay đổi sâu sắc với sự sụp đổ của hệ thống thuộc địa. Tại châu Phi, quá trình này diễn ra không đồng nhất về phương pháp nhưng thống nhất về mục tiêu: giành lại quyền tự quyết. Từ những cuộc binh biến tại Bắc Phi đầu những năm 50, đến phong trào đấu tranh vũ trang bền bỉ ở Ăng-gô-la, Mô-dăm-bích, và đỉnh cao là cuộc đấu tranh chính trị nhằm xóa bỏ tận gốc chế độ phân biệt chủng tộc (Apartheid) tại Nam Phi.<br>Tuy nhiên, độc lập về chính trị mới chỉ là bước khởi đầu. Các quốc gia châu Phi sau khi giành chủ quyền đã phải đối mặt với những &#x27;di sản độc hại&#x27; từ chủ nghĩa thực dân: biên giới lãnh thổ bị chia cắt tùy tiện, nền kinh tế què quặt phụ thuộc vào xuất khẩu nguyên liệu thô và những xung đột sắc tộc dai dẳng. Hành trình của châu Phi trong thế kỉ XXI không còn là cầm súng giành độc lập, mà là cuộc chiến chống nghèo đói, dịch bệnh và hội nhập vào nền kinh tế toàn cầu.&quot;<br><i>(Nguồn: SGK Lịch sử 12 - Bộ Kết nối tri thức &amp; Cánh diều)</i>", "cauHoi": [{"question": "<b>Điểm khác biệt tiêu biểu của phong trào giải phóng dân tộc ở Nam Phi so với khu vực Bắc Phi và Tây Phi trong thế kỉ XX là gì?</b>", "choices": ["Là cuộc đấu tranh chống lại sự xâm lược của các nước phát triển.", "Mục tiêu chủ yếu là đánh đổ nền thống trị của chủ nghĩa thực dân cũ.", "Đối tượng đấu tranh trực tiếp là chế độ phân biệt chủng tộc cực đoan.", "Diễn ra chủ yếu dưới hình thức khởi nghĩa vũ trang và chiến tranh cách mạng."], "correctIndex": 2, "explain": "<b>Câu 1 chọn đáp án C</b><br><b>Giải thích:</b> Khác với khu vực Bắc Phi (thường đấu tranh chống lại sự chiếm đóng của thực dân Anh, Pháp), phong trào ở Nam Phi có đặc thù là cuộc đấu tranh chống lại chế độ phân biệt chủng tộc (Apartheid) do chính quyền của người da trắng thiểu số thiết lập. Đây là cuộc đấu tranh vì quyền con người và sự bình đẳng sắc tộc, một nét riêng biệt của lịch sử khu vực này."}, {"question": "<b>Theo tư liệu, đâu là một trong những &quot;di sản độc hại&quot; của chủ nghĩa thực dân để lại cho các nước châu Phi?</b>", "choices": ["Sự thiếu hụt nguồn tài nguyên thiên nhiên cho phát triển công nghiệp.", "Các đường biên giới lãnh thổ được phân chia không dựa trên thực tế tộc người.", "Sự biến mất hoàn toàn của các giá trị văn hóa truyền thống bản địa.", "Việc các nước này không thể gia nhập vào các tổ chức quốc tế như Liên hợp quốc."], "correctIndex": 1, "explain": "<b>Câu 2 chọn đáp án B</b><br><b>Giải thích:</b> Trong đoạn tư liệu có nêu rõ các nước châu Phi phải đối mặt với <i>&quot;biên giới lãnh thổ bị chia cắt tùy tiện&quot;</i>. Thực tế lịch sử cho thấy, các thực dân châu Âu khi phân chia thuộc địa đã dùng thước kẻ trên bản đồ mà không tính đến yếu tố phân bố sắc tộc, bộ lạc, dẫn đến tình trạng một bộ lạc bị chia cắt ở hai quốc gia khác nhau, gây ra xung đột dai dẳng sau khi giành độc lập."}, {"question": "<b>Nội dung nào sau đây phản ánh đúng tính chất của phong trào giải phóng dân tộc ở châu Phi sau Chiến tranh thế giới thứ hai?</b>", "choices": ["Một cuộc cách mạng tư sản dân quyền do giai cấp công nhân lãnh đạo.", "Quá trình chuyển đổi từ chủ nghĩa thực dân cũ sang chủ nghĩa thực dân mới.", "Cuộc đấu tranh vì quyền con người và quyền tự quyết dân tộc cơ bản.", "Một bộ phận của cuộc Cách mạng khoa học - kĩ thuật hiện đại."], "correctIndex": 2, "explain": "<b>Câu 3 chọn đáp án C</b><br><b>Giải thích:</b> Phong trào giải phóng dân tộc ở châu Phi không chỉ dừng lại ở việc thay đổi bộ máy chính quyền mà cốt lõi là đòi quyền tự quyết dân tộc (giành độc lập) và quyền sống của con người (xóa bỏ nô dịch, phân biệt đối xử). Các phương án khác như cách mạng vô sản hay chủ nghĩa thực dân mới thường gắn liền với những bối cảnh hoặc khu vực khác hơn là đặc trưng chung của toàn châu lục này."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN KTPL - Dựa vào thông tin dưới đây để trả lời các Câu từ 118 đến 120 </b><br>Trong nền kinh tế thị trường, các cá nhân và doanh nghiệp tương tác với nhau để quyết định việc sản xuất và tiêu dùng. Cơ chế thị trường là hệ thống các quan hệ kinh tế tự điều chỉnh dựa trên tác động của các quy luật kinh tế khách quan như quy luật cung - cầu, quy luật giá cả và quy luật cạnh tranh.<br>Adam Smith, cha đẻ của kinh tế học hiện đại, đã dùng thuật ngữ <b>&quot;bàn tay vô hình&quot;</b> để mô tả cách thức mà thị trường tự vận hành. Theo đó, khi mỗi cá nhân chỉ theo đuổi lợi ích riêng của chính mình, họ thường thúc đẩy lợi ích của xã hội một cách hiệu quả hơn cả khi họ thực sự định làm điều đó. Ví dụ, một người sản xuất muốn tối đa hóa lợi nhuận sẽ phải cải tiến kỹ thuật, giảm chi phí và nâng cao chất lượng sản phẩm để thu hút khách hàng. Kết quả là người tiêu dùng có hàng hóa tốt hơn với giá rẻ hơn, và nền kinh tế trở nên năng động hơn.<br>Tuy nhiên, cơ chế thị trường không phải là &quot;chiếc đũa thần&quot; vạn năng. Nó vẫn tồn tại những khiếm khuyết (thất bại của thị trường) như: sự xuất hiện của độc quyền, ô nhiễm môi trường (ngoại ứng tiêu cực) hay sự phân hóa giàu nghèo sâu sắc. Chính vì vậy, để nền kinh tế phát triển ổn định và công bằng, cần có <b>sự điều tiết của Nhà nước</b> thông qua pháp luật và các chính sách kinh tế vĩ mô.", "cauHoi": [{"question": "<b>Theo nội dung bài đọc, yếu tố nào đóng vai trò cốt lõi trong việc hình thành cơ chế thị trường?</b>", "choices": ["Sự chỉ đạo tuyệt đối của các cơ quan quản lý nhà nước.", "Các quy luật kinh tế khách quan như cung - cầu, giá cả, cạnh tranh.", "Ý muốn chủ quan của các doanh nghiệp lớn trên thị trường.", "Các hoạt động từ thiện và cứu trợ xã hội của doanh nghiệp."], "correctIndex": 1, "explain": "<b>Chọn đáp án B</b><br><b>Dựa vào đoạn 1: &quot;Cơ chế thị trường là hệ thống... tự điều chỉnh dựa trên các quy luật kinh tế khách quan&quot;.</b>"}, {"question": "<b>Thuật ngữ &quot;bàn tay vô hình&quot; của Adam Smith nhấn mạnh điều gì trong kinh tế thị trường?</b>", "choices": ["Nhà nước cần can thiệp bí mật vào các hoạt động kinh doanh.", "Người sản xuất luôn tìm cách lừa dối người tiêu dùng để trục lợi.", "Việc theo đuổi lợi ích cá nhân một cách hợp pháp có thể mang lại lợi ích cho cộng đồng.", "Thị trường luôn hoạt động hoàn hảo mà không bao giờ gặp sự cố."], "correctIndex": 2, "explain": "<b>Chọn đáp án C</b><br><b>Dựa vào đoạn 2: &quot;khi mỗi cá nhân chỉ theo đuổi lợi ích riêng... họ thường thúc đẩy lợi ích của xã hội&quot;.</b>"}, {"question": "<b>Đâu là một ví dụ về &quot;khiếm khuyết của thị trường&quot; được đề cập trong văn bản?</b>", "choices": ["Doanh nghiệp cải tiến kỹ thuật để giảm giá thành sản phẩm.", "Người tiêu dùng tự do lựa chọn hàng hóa phù hợp với túi tiền.", "Sự phân hóa giàu nghèo quá mức và vấn đề ô nhiễm môi trường.", "Sự tương tác giữa người mua và người bán để xác định giá cả."], "correctIndex": 3, "explain": "<b>Chọn đáp án D</b><br><b>Dựa vào đoạn 3: Liệt kê các khiếm khuyết gồm độc quyền, ô nhiễm, phân hóa giàu nghèo.</b>"}], "khongXaoTron": true}]};
